/*
 * RoadSafe Blender Color Guard V3
 * Final defensive UI colour layer.
 */

:root {
  --roadsafe-ui-accent: #e8872d;
  --roadsafe-ui-shell: #1b1b1b;
  --roadsafe-ui-workspace: #202020;
  --roadsafe-ui-panel: #292929;
  --roadsafe-ui-section: #303030;
  --roadsafe-ui-raised: #383838;
  --roadsafe-ui-hover: #414141;
  --roadsafe-ui-input: #202020;
  --roadsafe-ui-border: #171717;
  --roadsafe-ui-border-mid: #494949;
  --roadsafe-ui-border-strong: #5c5c5c;
  --roadsafe-ui-text: #dedede;
  --roadsafe-ui-text-secondary: #c4c4c4;
  --roadsafe-ui-muted: #969696;
}

html,
body,
#root {
  background: var(--roadsafe-ui-shell) !important;
  color: var(--roadsafe-ui-text) !important;
}

.roadsafe-workstation,
.roadsafe-center,
.roadsafe-center-content,
.reconstruction-shell-main,
.reconstruction-workspace,
main {
  background-color: var(--roadsafe-ui-workspace) !important;
}

.ui-panel,
.workstation-panel,
.roadsafe-inspector,
.roadsafe-bottom-panel,
.reconstruction-workspace__properties,
.reconstruction-workspace__settings,
.reconstruction-workspace__timeline,
.reconstruction-workspace__workspace-card,
.reconstruction-node-editor,
.blender-object-category,
.blender-placed-objects,
.scene-settings__section {
  border-color: var(--roadsafe-ui-border) !important;
  background-color: var(--roadsafe-ui-panel) !important;
  background-image: none !important;
}

.ui-button,
.ui-button-primary,
.ui-icon-button,
.reconstruction-workspace__button,
.reconstruction-workspace__icon-button,
.reconstruction-workspace__view-switch button {
  border-color: var(--roadsafe-ui-border-mid) !important;
  background:
    linear-gradient(
      180deg,
      #444 0%,
      #343434 100%
    ) !important;
  color: #d0d0d0 !important;
}

button.is-active,
[aria-pressed="true"],
.reconstruction-workspace__view-switch button.is-active,
.reconstruction-workspace__tools button.is-active {
  border-color: var(--roadsafe-ui-accent) !important;
  background:
    linear-gradient(
      180deg,
      #46413d 0%,
      #39332f 100%
    ) !important;
  color: #fff !important;
  box-shadow:
    inset 3px 0 0 var(--roadsafe-ui-accent) !important;
}

input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
select,
textarea,
.ui-input {
  border-color: var(--roadsafe-ui-border-mid) !important;
  background: var(--roadsafe-ui-input) !important;
  color: var(--roadsafe-ui-text) !important;
}

input:focus,
select:focus,
textarea:focus,
button:focus-visible,
summary:focus-visible {
  border-color: var(--roadsafe-ui-accent) !important;
  outline: none !important;
  box-shadow: 0 0 0 1px var(--roadsafe-ui-accent) !important;
}

input[type="checkbox"],
input[type="radio"],
input[type="range"],
.roadsafe-range {
  accent-color: var(--roadsafe-ui-accent) !important;
}

.maplibregl-ctrl-group,
.maplibregl-popup-content {
  border-color: var(--roadsafe-ui-border-mid) !important;
  background: var(--roadsafe-ui-panel) !important;
  color: var(--roadsafe-ui-text) !important;
}

/* [RoadSafe:ReconstructionBlenderPropertiesV4:start] */

.reconstruction-workspace__stage-grid--3d {
  grid-template-columns:
    minmax(0, 1fr)
    326px !important;
}

.reconstruction-workspace__blender-properties {
  width: 326px !important;
  min-width: 326px !important;
  max-width: 326px !important;
  height: 100% !important;
  min-height: 0 !important;

  display: grid !important;
  grid-template-columns:
    34px minmax(0, 1fr) !important;

  overflow: hidden !important;

  border: 0 !important;
  border-left:
    1px solid #151515 !important;
  border-radius: 0 !important;

  background: #292929 !important;
  color: #d5d5d5 !important;

  box-shadow:
    inset 1px 0 0 rgba(255,255,255,.025) !important;
}

/* ------------------------------------------------------------------------- */
/* Real Blender-like properties tab rail                                    */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-tabs {
  min-width: 0 !important;
  height: 100% !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;

  padding: 5px 0 !important;

  border-right:
    1px solid #161616 !important;

  background: #232323 !important;
}

.reconstruction-workspace__blender-properties-tabs
  button {
  position: relative !important;

  width: 34px !important;
  min-width: 34px !important;
  height: 34px !important;
  min-height: 34px !important;

  display: grid !important;
  place-items: center !important;

  padding: 0 !important;
  margin: 0 !important;

  border: 0 !important;
  border-left:
    2px solid transparent !important;
  border-radius: 0 !important;

  background: transparent !important;
  color: #8f8f8f !important;

  box-shadow: none !important;

  transform: none !important;
}

.reconstruction-workspace__blender-properties-tabs
  button:hover {
  background: #303030 !important;
  color: #d7d7d7 !important;
}

.reconstruction-workspace__blender-properties-tabs
  button.is-active,
.reconstruction-workspace__blender-properties-tabs
  button[aria-pressed="true"] {
  border-left-color:
    #e8872d !important;

  background: #343434 !important;
  color: #ededed !important;

  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.025) !important;
}

.reconstruction-workspace__blender-properties-tabs
  button.is-active::after,
.reconstruction-workspace__blender-properties-tabs
  button[aria-pressed="true"]::after {
  content: "" !important;

  position: absolute !important;
  right: -1px !important;
  top: 5px !important;
  bottom: 5px !important;

  width: 1px !important;

  background: #343434 !important;
}

/* ------------------------------------------------------------------------- */
/* Main editor                                                               */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-editor {
  min-width: 0 !important;
  min-height: 0 !important;

  display: flex !important;
  flex-direction: column !important;

  overflow: hidden !important;

  background: #292929 !important;
}

.reconstruction-workspace__blender-properties-header {
  min-height: 40px !important;
  height: 40px !important;

  flex: 0 0 40px !important;

  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;

  gap: 8px !important;

  padding: 5px 7px 5px 9px !important;

  border-bottom:
    1px solid #171717 !important;

  background:
    linear-gradient(
      180deg,
      #343434 0%,
      #2c2c2c 100%
    ) !important;
}

.reconstruction-workspace__blender-properties-header
  > div {
  min-width: 0 !important;

  display: flex !important;
  flex-direction: column !important;

  gap: 2px !important;
}

.reconstruction-workspace__blender-properties-header
  span {
  color: #8f8f8f !important;

  font-size: 9px !important;
  font-weight: 500 !important;
  line-height: 1 !important;
}

.reconstruction-workspace__blender-properties-header
  strong {
  max-width: 220px !important;

  overflow: hidden !important;

  color: #dadada !important;

  font-size: 11px !important;
  font-weight: 650 !important;
  line-height: 1.1 !important;

  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.reconstruction-workspace__blender-properties-header
  > button {
  width: 23px !important;
  min-width: 23px !important;
  height: 23px !important;
  min-height: 23px !important;

  padding: 0 !important;

  border:
    1px solid transparent !important;
  border-radius: 2px !important;

  background: transparent !important;
  color: #a7a7a7 !important;

  font-size: 15px !important;

  box-shadow: none !important;
}

.reconstruction-workspace__blender-properties-header
  > button:hover {
  border-color: #4b4b4b !important;
  background: #3a3a3a !important;
  color: #fff !important;
}

.reconstruction-workspace__blender-properties-content {
  min-height: 0 !important;
  flex: 1 1 auto !important;

  overflow-x: hidden !important;
  overflow-y: auto !important;

  padding: 3px 0 12px !important;

  background: #292929 !important;

  scrollbar-width: thin !important;
  scrollbar-color:
    #555 #232323 !important;
}

.reconstruction-workspace__blender-properties-content::-webkit-scrollbar {
  width: 9px !important;
}

.reconstruction-workspace__blender-properties-content::-webkit-scrollbar-track {
  background: #232323 !important;
}

.reconstruction-workspace__blender-properties-content::-webkit-scrollbar-thumb {
  border:
    2px solid #232323 !important;
  border-radius: 2px !important;

  background: #555 !important;
}

/* ------------------------------------------------------------------------- */
/* Blender disclosure panels                                                */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-section {
  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;
  border-bottom:
    1px solid #181818 !important;
  border-radius: 0 !important;

  background: #292929 !important;

  box-shadow: none !important;
}

.reconstruction-workspace__blender-properties-section
