  background: #353535 !important;
  color: #ededed !important;
}

/* ------------------------------------------------------------------------- */
/* Property rows                                                            */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-rows {
  display: grid !important;

  gap: 0 !important;

  padding: 4px 8px 7px !important;

  background: #292929 !important;
