  > span,
.reconstruction-workspace__blender-properties-rows
  > div
  > span {
  color: #979797 !important;

  font-size: 10.5px !important;
  font-weight: 500 !important;
  line-height: 1.05 !important;
}

.reconstruction-workspace__blender-properties-rows
