  border-color:
    #e8872d !important;

  outline: 0 !important;

  box-shadow:
    0 0 0 1px rgba(232,135,45,.12),
    inset 0 1px 2px rgba(0,0,0,.42) !important;
}

/* ------------------------------------------------------------------------- */
/* Compact checkbox list                                                    */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-checks {
  display: grid !important;

  gap: 0 !important;

  padding: 4px 8px 7px !important;

  background: #292929 !important;
}

.reconstruction-workspace__blender-properties-checks
