  width: 14px !important;
  min-width: 14px !important;
  height: 14px !important;

  margin: 0 !important;

  accent-color:
    #e8872d !important;
}

/* ------------------------------------------------------------------------- */
/* Empty state                                                              */
/* ------------------------------------------------------------------------- */

.reconstruction-workspace__blender-properties-empty {
  margin: 7px !important;
  padding: 10px !important;

  border:
    1px dashed #464646 !important;
  border-radius: 2px !important;

  background: #272727 !important;
  color: #969696 !important;

  font-size: 10.5px !important;
  line-height: 1.4 !important;
}

@media (max-width: 1180px) {
  .reconstruction-workspace__stage-grid--3d {
    grid-template-columns:
      minmax(0, 1fr)
      304px !important;
  }

  .reconstruction-workspace__blender-properties {
    width: 304px !important;
    min-width: 304px !important;
    max-width: 304px !important;
  }

  .reconstruction-workspace__blender-properties-rows
    > label,
  .reconstruction-workspace__blender-properties-rows
    > div {
    grid-template-columns:
      72px minmax(0, 1fr) !important;
  }
}

/* [RoadSafe:ReconstructionBlenderPropertiesV4:end] */

